1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strconv"
10		"unicode/utf8"
11	)
12	
13	// EvalReason is the machine-readable outcome of a flag evaluation.
14	type EvalReason string
15	
16	const (
17		EvalDisabled EvalReason = "disabled"
18		EvalRule     EvalReason = "rule"
19		EvalDefault  EvalReason = "default"
20	)
21	
22	// Condition is one predicate over an evaluation context.
23	type Condition struct {
24		Attribute string
25		Op        string
26		// strVal 用于 eq；inVal 用于 in（至少一项）。
27		strVal string
28		inVal  []string
29	}
30	
31	// Rule groups conditions that must all hold; on match the flag takes Value.
32	type Rule struct {
33		ID         string
34		Value      bool
35		Conditions []Condition
36	}
37	
38	// Flag is one feature toggle with its default and ordered rules.
39	type Flag struct {
40		Key     string
41		Enabled bool
42		Default bool
43		Rules   []Rule
44	}
45	
46	// Config is a validated feature flag configuration.
47	type Config struct {
48		Flags []Flag
49	}
50	
51	// EvalResult is the deterministic outcome of evaluating one flag.
52	type EvalResult struct {
53		Key    string     `json:"key"`
54		Value  bool       `json:"value"`
55		Reason EvalReason `json:"reason"`
56		RuleID *string    `json:"ruleId"`
57	}
58	
59	// Equals reports whether two evaluation results are identical.
60	func (r EvalResult) Equals(other EvalResult) bool {
61		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
62			return false
63		}
64		if (r.RuleID == nil) != (other.RuleID == nil) {
65			return false
66		}
67		if r.RuleID != nil && *r.RuleID != *other.RuleID {
68			return false
69		}
70		return true
71	}
72	
73	// ConditionExplanation 记录单个条件在给定上下文上的判断：属性名、比较方式
74	// （eq/in）、配置中的比较值、上下文实际值以及条件是否成立。属性缺失时
75	// Missing 为 true 且 ActualValue 为 nil——与显式给出的空字符串
76	// （ActualValue 指向 ""、Missing 为 false）明确区分。
77	type ConditionExplanation struct {
78		Attribute    string `json:"attribute"`
79		Op           string `json:"op"`
80		CompareValue any    `json:"compareValue"`
81		// ActualValue 为上下文实际值；属性缺失时为 nil 并把 Missing 置为 true。
82		ActualValue *string `json:"actualValue"`
83		Missing     bool    `json:"missing"`
84		Match       bool    `json:"match"`
85	}
86	
87	// RuleExplanation 记录一条被考虑过的规则：规则编号、是否整体命中以及它的
88	// 全部条件逐条判断结果（即使规则在首个失败条件后已确定不命中，其余条件的
89	// 判断也照样给出）。
90	type RuleExplanation struct {
91		RuleID     string                 `json:"ruleId"`
92		Match      bool                   `json:"match"`
93		Conditions []ConditionExplanation `json:"conditions"`
94	}
95	
96	// EvalExplanation 是解释模式附加在结果对象上的判断过程。Outcome 用一句话
97	// 说明最终结果的依据；Rules 按配置顺序列出实际考虑过的规则，到第一条全部
98	// 条件成立的规则为止（含该规则），开关关闭时为空列表。
99	type EvalExplanation struct {
100		Outcome string            `json:"outcome"`
101		Rules   []RuleExplanation `json:"rules"`
102	}
103	
104	// ExplainedResult 是解释模式的输出：四个既有字段与普通模式逐字一致，
105	// 另带 explanation 判断记录。
106	type ExplainedResult struct {
107		EvalResult
108		Explanation EvalExplanation `json:"explanation"`
109	}
110	
111	// Context is a validated map of attribute names to string values.
112	type Context struct {
113		values map[string]string
114	}
115	
116	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
117	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
118	func LoadConfig(path string) (*Config, error) {
119		raw, err := os.ReadFile(path)
120		if err != nil {
121			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
122		}
123		return ParseConfig(raw)
124	}
125	
126	// LoadContext reads and validates a UTF-8 JSON context file.
127	func LoadContext(path string) (*Context, error) {
128		raw, err := os.ReadFile(path)
129		if err != nil {
130			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
131		}
132		return ParseContext(raw)
133	}
134	
135	// unmarshalStrictJSON 严格解码一个 UTF-8 JSON 文档到 any，并保持与
136	// json.Unmarshal 相同的单文档语义：文档之后只允许空白，不允许第二个值。
137	// 使用 json.Decoder + UseNumber：数字按原文保留为 json.Number，而不是强制
138	// 转成 float64——语法合法但超出浮点范围的数字（如 1e400、由 1 后接 400 个 0
139	// 组成的整数）不应被当成“JSON 无效”，它们是合法的 JSON 数字，由后续的值
140	// 类型检查以所属字段的类型错误报告。
141	func unmarshalStrictJSON(raw []byte) (any, error) {
142		dec := json.NewDecoder(bytes.NewReader(raw))
143		dec.UseNumber()
144		var doc any
145		if err := dec.Decode(&doc); err != nil {
146			return nil, err
147		}
148		// Decoder 本身容忍文档之后的额外 JSON 值，需显式补回 Unmarshal 的严格性。
149		offset := int(dec.InputOffset())
150		var extra any
151		if err := dec.Decode(&extra); err != io.EOF {
152			if err != nil {
153				return nil, err
154			}
155			for offset < len(raw) && isJSONWhitespace(raw[offset]) {
156				offset++
157			}
158			c := byte(0)
159			if offset < len(raw) {
160				c = raw[offset]
161			}
162			return nil, fmt.Errorf("invalid character %q after top-level value", c)
163		}
164		return doc, nil
165	}
166	
167	// isJSONWhitespace 报告 b 是否为 JSON 允许的空白字节。
168	func isJSONWhitespace(b byte) bool {
169		return b == ' ' || b == '\t' || b == '\n' || b == '\r'
170	}
171	
172	// parseJSONDocument 执行配置与上下文两类输入共同维护的文档格式校验，使两份
173	// JSON 对同一组格式规则给出一致的接受结果与错误定位。检查按固定先后顺序报告
174	// 原文中的第一处问题：
175	//  1. 非法 UTF-8 字节——最先检查，不被其后任何错误遮住；
176	//  2. 不能组成完整字符的 \uXXXX 转义（字段名与字符串值同等检查）——先于
177	//     重复字段，避免 encoding/json 把孤立代理项静默替换成 U+FFFD 后误判重复；
178	//  3. 同一对象内的重复字段——先于业务字段问题；
179	//  4. JSON 语法与单文档边界：只接受一个顶层值，完整文档后只允许空白，
180	//     第二个值或其他尾随内容一律拒绝；
181	//  5. 顶层必须是一个 JSON 对象。
182	//
183	// 这一步只判定文档格式：数字一律按原文保留（json.Number），语法合法但超出
184	// 浮点范围的大数字不在此拒绝；具体字段的类型/必填/唯一性属于各自的业务规则，
185	// 由调用方在取得 root 后按配置或上下文的约定继续校验。label 是本文档在错误
186	// 信息中的名字（"config" 或 "context"）。
187	func parseJSONDocument(raw []byte, label string) (map[string]any, error) {
188		if !utf8.Valid(raw) {
189			return nil, fmt.Errorf("%s: file is not valid UTF-8", label)
190		}
191		if err := rejectInvalidUnicodeEscapes(raw, label); err != nil {
192			return nil, err
193		}
194		if err := rejectDuplicateFields(raw, label); err != nil {
195			return nil, err
196		}
197		doc, err := unmarshalStrictJSON(raw)
198		if err != nil {
199			return nil, fmt.Errorf("%s: invalid JSON: %w", label, err)
200		}
201		root, ok := doc.(map[string]any)
202		if !ok {
203			return nil, fmt.Errorf("%s: top level must be a JSON object", label)
204		}
205		return root, nil
206	}
207	
208	// ParseConfig parses a config document from JSON bytes with strict typing.
209	// 文档格式校验由 parseJSONDocument 与 ParseContext 共同维护；这里只继续处理
210	// 配置自身的业务字段（开关、规则、条件与唯一性）。先解析到 any 再逐字段校验，
211	// 以区分“字段缺失”与“显式提供的 false”。
212	func ParseConfig(raw []byte) (*Config, error) {
213		root, err := parseJSONDocument(raw, "config")
214		if err != nil {
215			return nil, err
216		}
217		flagsRaw, present := root["flags"]
218		if !present {
219			return nil, fmt.Errorf("config.flags: field is required")
220		}
221		if flagsRaw == nil {
222			return nil, fmt.Errorf("config.flags: must be an array, got null")
223		}
224		flagsArr, ok := flagsRaw.([]any)
225		if !ok {
226			return nil, fmt.Errorf("config.flags: must be an array")
227		}
228		cfg := &Config{}
229		seenKeys := map[string]int{}
230		for i, fr := range flagsArr {
231			flag, err := parseFlag(fr, i)
232			if err != nil {
233				return nil, err
234			}
235			if prev, dup := seenKeys[flag.Key]; dup {
236				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
237			}
238			seenKeys[flag.Key] = i
239			cfg.Flags = append(cfg.Flags, flag)
240		}
241		return cfg, nil
242	}
243	
244	// ParseContext parses an attribute-name -> string context object; it may be empty.
245	// 文档格式校验由 parseJSONDocument 与 ParseConfig 共同维护；这里只继续检查
246	// 上下文自身的业务规则：每个顶层属性的值都必须是字符串。
247	func ParseContext(raw []byte) (*Context, error) {
248		root, err := parseJSONDocument(raw, "context")
249		if err != nil {
250			return nil, err
251		}
252		// 语法校验通过后才建立可用属性：值类型检查与属性建立在同一次遍历中完成。
253		return buildContext(raw, root)
254	}
255	
256	// buildContext 按文件原文顺序做一次流式遍历，同时完成顶层属性的值类型检查
257	// 与可用属性的建立：字段名顺序取自令牌流（Go map 的遍历顺序不稳定，不能
258	// 直接 range root，否则同一文件在不同运行中可能报告不同属性），属性值复用
259	// 严格解码得出的 root——同一份上下文的值只解码一次。语法、重复字段与 Unicode
260	// 转义已在此前校验，这里的令牌读取不会再遇到错误。键名使用解码后的文字
261	// （合法的 \uXXXX 转义与直接字符同义；大小写与空白按原样保留）。对象或数组
262	// 值整体算所属顶层属性的一个值，错误不指向其内部成员。
263	func buildContext(raw []byte, root map[string]any) (*Context, error) {
264		dec := json.NewDecoder(bytes.NewReader(raw))
265		// 消费顶层对象的 '{'；语法已由 unmarshalStrictJSON 校验。
266		if _, err := dec.Token(); err != nil {
267			return nil, fmt.Errorf("context: invalid JSON: %w", err)
268		}
269		ctx := &Context{values: make(map[string]string, len(root))}
270		for dec.More() {
271			keyTok, err := dec.Token()
272			if err != nil {
273				return nil, fmt.Errorf("context: invalid JSON: %w", err)
274			}
275			key, _ := keyTok.(string)
276			// 值不再重复解码：RawMessage 只把读取位置推进到下一个字段，
277			// 实际值取自已严格解码的 root。数字（含超出浮点范围的 json.Number）、
278			// 布尔、null、对象、数组都在这里按所属属性报类型错误。
279			var skipped json.RawMessage
280			if err := dec.Decode(&skipped); err != nil {
281				return nil, fmt.Errorf("context: invalid JSON: %w", err)
282			}
283			s, ok := root[key].(string)
284			if !ok {
285				return nil, fmt.Errorf("%s: value must be a string", appendFieldPath("context", key))
286			}
287			ctx.values[key] = s
288		}
289		return ctx, nil
290	}
291	
292	// Get looks up an attribute; an empty string is a legal value.
293	func (c *Context) Get(attribute string) (string, bool) {
294		if c == nil {
295			return "", false
296		}
297		v, ok := c.values[attribute]
298		return v, ok
299	}
300	
301	// Find returns the flag with the given key, or nil if absent.
302	func (c *Config) Find(key string) *Flag {
303		if c == nil {
304			return nil
305		}
306		for i := range c.Flags {
307			if c.Flags[i].Key == key {
308				return &c.Flags[i]
309			}
310		}
311		return nil
312	}
313	
314	// evaluate 是普通模式与解释模式共同维护的唯一定案路径：关闭固定 false
315	// （reason=disabled），不使用默认值或规则；启用后取首条所有条件均成立的规则的
316	// value（即使它返回 false 也立即定案，后续规则不再考虑）；无匹配取 default。
317	// 求值不依赖时间、随机数或 map 遍历顺序。定案所依据的逐条条件判断与规则遍历过程
318	// 一并记录在返回值中，普通模式只取其中的结果字段，解释模式额外展示判断记录，
319	// 因此两种模式对同一份配置与上下文不可能给出不同判断。
320	func (f *Flag) evaluate(ctx *Context) evaluation {
321		result := EvalResult{Key: f.Key}
322		if !f.Enabled {
323			return evaluation{
324				result:  EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil},
325				outcome: "flag is disabled; result is fixed to false without evaluating rules or the default",
326				rules:   []RuleExplanation{},
327			}
328		}
329		// considered 按配置顺序收集定案前实际考虑过的规则，到第一条全部条件成立的
330		// 规则为止（含该规则）；无规则或全部不命中时为空列表而非 nil。
331		considered := make([]RuleExplanation, 0, len(f.Rules))
332		for i := range f.Rules {
333			rule := &f.Rules[i]
334			re := rule.evaluate(ctx)
335			considered = append(considered, re)
336			if re.Match {
337				id := rule.ID
338				result = EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
339				return evaluation{
340					result:  result,
341					outcome: fmt.Sprintf("first matching rule %q decides the result; later rules are not considered", rule.ID),
342					rules:   considered,
343				}
344			}
345		}
346		result = EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
347		return evaluation{
348			result:  result,
349			outcome: "no rule matched; the flag default is used",
350			rules:   considered,
351		}
352	}
353	
354	// evaluation 是一次求值的完整记录：定案的四字段结果、一句话依据以及按配置顺序
355	// 考虑过的规则判断记录。普通模式只用 Result；解释模式三者都输出。
356	type evaluation struct {
357		result  EvalResult
358		outcome string
359		rules   []RuleExplanation
360	}
361	
362	// Evaluate deterministically evaluates a flag against a context；定案规则与判断
363	// 细节统一由 evaluate 维护，本入口只返回四字段结果。
364	func (f *Flag) Evaluate(ctx *Context) EvalResult {
365		return f.evaluate(ctx).result
366	}
367	
368	// EvaluateExplain 与 Evaluate 走同一条 evaluate 定案路径（关闭固定 false、
369	// 首条全部条件成立的规则决定结果、否则取 default），并额外把该路径产出的判断
370	// 记录作为 explanation：每条在定案前被考虑过的规则都给出 id、是否命中与全部
371	// 条件的逐条判断；第一条命中的规则（即使返回 false）也计入并立即停止，其后的
372	// 规则不出现。开关关闭时不评估任何规则，解释中的规则列表为空，结果依据只
373	// 说明关闭导致固定 false。
374	func (f *Flag) EvaluateExplain(ctx *Context) ExplainedResult {
375		e := f.evaluate(ctx)
376		return ExplainedResult{
377			EvalResult: e.result,
378			Explanation: EvalExplanation{
379				Outcome: e.outcome,
380				Rules:   e.rules,
381			},
382		}
383	}
384	
385	// evaluate 判断一条规则的全部条件并逐条记录判断结果；Match 为所有条件都
386	// 成立。它不会在首个失败条件处短路，因此每个条件的属性、比较值、实际值与
387	// 是否成立都能展示出来，规则整体的命中判断与条件逐条判断共用这一份结果。
388	func (r *Rule) evaluate(ctx *Context) RuleExplanation {
389		re := RuleExplanation{RuleID: r.ID, Match: true, Conditions: make([]ConditionExplanation, 0, len(r.Conditions))}
390		for i := range r.Conditions {
391			ce := r.Conditions[i].evaluate(ctx)
392			re.Conditions = append(re.Conditions, ce)
393			if !ce.Match {
394				re.Match = false
395			}
396		}
397		if len(re.Conditions) == 0 {
398			// 解析阶段已要求规则至少含一个条件，这里只是防御性处理，避免无条件的
399			// 规则被当成命中。
400			re.Match = false
401		}
402		return re
403	}
404	
405	// evaluate 判断单个条件并记录属性名、比较方式、配置比较值、上下文实际值与
406	// 是否成立；规则与开关各层级的“条件是否成立”都以这里的 Match 为准，普通模式
407	// 与解释模式不再各算一遍。属性缺失用 Missing=true、ActualValue=nil 表示，
408	// 绝不与显式空字符串（ActualValue 指向 ""）混淆。
409	func (c Condition) evaluate(ctx *Context) ConditionExplanation {
410		ce := ConditionExplanation{Attribute: c.Attribute, Op: c.Op}
411		switch c.Op {
412		case "eq":
413			ce.CompareValue = c.strVal
414		case "in":
415			// 复制一份，避免外部切片与解释记录共享底层数组。
416			list := make([]string, len(c.inVal))
417			copy(list, c.inVal)
418			ce.CompareValue = list
419		default:
420			// 解析阶段已拒绝未知运算符，防御性处理。
421			ce.CompareValue = nil
422		}
423		v, present := ctx.Get(c.Attribute)
424		if !present {
425			ce.Missing = true
426			ce.Match = false
427			return ce
428		}
429		ce.ActualValue = &v
430		switch c.Op {
431		case "eq":
432			ce.Match = v == c.strVal
433		case "in":
434			for _, candidate := range c.inVal {
435				if v == candidate {
436					ce.Match = true
437					break
438				}
439			}
440		default:
441			ce.Match = false
442		}
443		return ce
444	}
445	
446	// MarshalResult renders the result as a single compact JSON object.
447	func MarshalResult(r EvalResult) ([]byte, error) {
448		var buf bytes.Buffer
449		enc := json.NewEncoder(&buf)
450		enc.SetEscapeHTML(false)
451		if err := enc.Encode(r); err != nil {
452			return nil, err
453		}
454		return bytes.TrimRight(buf.Bytes(), "\n"), nil
455	}
456	
457	// MarshalExplain renders an explained result as a single compact JSON object:
458	// key/value/reason/ruleId 四个字段与 MarshalResult 逐字一致，其后追加
459	// explanation 判断记录；列表中的空字符串、重复成员与次序原样保留，不裁剪
460	// 空白、不合并大小写。
461	func MarshalExplain(r ExplainedResult) ([]byte, error) {
462		var buf bytes.Buffer
463		enc := json.NewEncoder(&buf)
464		enc.SetEscapeHTML(false)
465		if err := enc.Encode(r); err != nil {
466			return nil, err
467		}
468		return bytes.TrimRight(buf.Bytes(), "\n"), nil
469	}
470	
471	// --- strict parsing helpers -------------------------------------------------
472	
473	// isSimpleFieldName 报告字段名是否走点号连接：以 ASCII 字母或下划线开头，
474	// 其后只能含 ASCII 字母、数字、下划线。其他任何名字（含点号、方括号、空白、
475	// 空名、非 ASCII 字符）都改用方括号包住的 JSON 字符串定位，如
476	// context["user.name"]、context[""]。
477	func isSimpleFieldName(name string) bool {
478		if name == "" {
479			return false
480		}
481		for i := 0; i < len(name); i++ {
482			c := name[i]
483			// 非 ASCII 字节（UTF-8 续字节或首字节）一律不满足“仅 ASCII”的要求。
484			if c >= 0x80 {
485				return false
486			}
487			ok := ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || c == '_'
488			if i > 0 {
489				ok = ok || ('0' <= c && c <= '9')
490			}
491			if !ok {
492				return false
493			}
494		}
495		return true
496	}
497	
498	// appendFieldPath 在父位置后接上一个字段：简单字段名用点号连接，其余字段名
499	// 用方括号包住一个 JSON 字符串，引号、反斜杠与控制字符按 JSON 转义显示
500	// （Marshal 对 U+2028/U+2029 也会转义，但普通可见 Unicode 保持原样）。
501	// 名字按 JSON 解码后的文字传入，因此直接字符与合法 \uXXXX 转义得到同一位置。
502	func appendFieldPath(parent, name string) string {
503		if isSimpleFieldName(name) {
504			return parent + "." + name
505		}
506		return parent + "[" + jsonQuote(name) + "]"
507	}
508	
509	// jsonQuote 把字符串渲染为带双引号的 JSON 字符串字面量：引号、反斜杠与控制
510	// 字符按 JSON 转义（U+2028/U+2029 也会转义，避免定位文字被行分隔符拆行），
511	// 其余可见字符（含 <>& 与非 ASCII 文字）保持原样。
512	func jsonQuote(s string) string {
513		var buf bytes.Buffer
514		enc := json.NewEncoder(&buf)
515		enc.SetEscapeHTML(false)
516		if err := enc.Encode(s); err != nil {
517			// 不会发生：string 的 JSON 编码没有失败路径；保留一个确定的退路。
518			return strconv.Quote(s)
519		}
520		return string(bytes.TrimRight(buf.Bytes(), "\n"))
521	}
522	
523	// jsonFrame 是 JSON 原文遍历中一个对象或数组的层级状态。重复字段检查与非法
524	// Unicode 转义检查共用这一份层级与位置定义，调整错误定位时只需改这一处。
525	type jsonFrame struct {
526		path   string // 容器自身的完整位置，如 config.flags[0].rules[1]
527		object bool
528		// keys 记录本对象已声明的字段名（按解码后的字符串），仅重复字段检查使用；
529		// Unicode 遍历不登记字段，保持 nil。
530		keys map[string]struct{}
531		// lastKey 是对象最近一个字段名，用于拼出字段值的位置。
532		lastKey string
533		// expectKey 标记对象内下一个字符串是否为字段名。
534		expectKey bool
535		// nextIndex 是数组下一个元素的下标。
536		nextIndex int
537	}
538	
539	// jsonPathTracker 是两类 JSON 检查共用的对象层级、数组位置与字段路径状态机。
540	// label 是根容器的位置前缀（"config" 或 "context"）。
541	type jsonPathTracker struct {
542		label string
543		stack []*jsonFrame
544	}
545	
546	func newJSONPathTracker(label string) *jsonPathTracker {
547		return &jsonPathTracker{label: label}
548	}
549	
550	func (t *jsonPathTracker) top() *jsonFrame {
551		return t.stack[len(t.stack)-1]
552	}
553	
554	// childPath 拼出栈顶容器内下一个子值的位置：对象的字段值按 appendFieldPath
555	// 规则连接（简单名用点号，其余用方括号 JSON 字符串），数组元素用 [下标]。
556	func (t *jsonPathTracker) childPath() string {
557		top := t.top()
558		if top.object {
559			return appendFieldPath(top.path, top.lastKey)
560		}
561		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
562	}
563	
564	// beginContainer 在遇到 '{' 或 '[' 时压入新容器，返回新容器的完整位置。
565	func (t *jsonPathTracker) beginContainer(object bool) string {
566		path := t.label
567		if len(t.stack) > 0 {
568			path = t.childPath()
569		}
570		t.stack = append(t.stack, &jsonFrame{path: path, object: object, expectKey: object})
571		return path
572	}
573	
574	// endContainer 在遇到 '}' 或 ']' 时弹出容器，并把整个容器计为父容器中
575	// 一个已完成的值。
576	func (t *jsonPathTracker) endContainer() {
577		if len(t.stack) > 0 {
578			t.stack = t.stack[:len(t.stack)-1]
579		}
580		t.endValue()
581	}
582	
583	// atKey 报告下一个字符串是否应按对象字段名处理。
584	func (t *jsonPathTracker) atKey() bool {
585		return len(t.stack) > 0 && t.top().object && t.top().expectKey
586	}
587	
588	// currentPath 返回当前容器自身的位置（字段名报错时指向所属对象）；
589	// 栈为空时返回根标签。
590	func (t *jsonPathTracker) currentPath() string {
591		if len(t.stack) == 0 {
592			return t.label
593		}
594		return t.top().path
595	}
596	
597	// valuePath 拼出下一个字符串值（字段值或数组元素）的位置，但不改变状态。
598	func (t *jsonPathTracker) valuePath() string {
599		if len(t.stack) == 0 {
600			return t.label
601		}
602		return t.childPath()
603	}
604	
605	// endValue 在一个字段值或数组元素完成后调用：对象回到等待字段名的状态，
606	// 数组推进元素下标。
607	func (t *jsonPathTracker) endValue() {
608		if len(t.stack) == 0 {
609			return
610		}
611		top := t.top()
612		if top.object {
613			top.expectKey = true
614		} else {
615			top.nextIndex++
616		}
617	}
618	
619	// noteKey 登记一个已解码的对象字段名：更新字段路径状态，并在同一对象内第二次
620	// 声明同名字段时返回重复字段错误。
621	func (t *jsonPathTracker) noteKey(name string) error {
622		top := t.top()
623		if top.keys == nil {
624			top.keys = make(map[string]struct{})
625		}
626		if _, dup := top.keys[name]; dup {
627			return fmt.Errorf("%s: duplicate field %s", appendFieldPath(top.path, name), jsonQuote(name))
628		}
629		top.keys[name] = struct{}{}
630		top.lastKey = name
631		top.expectKey = false
632		return nil
633	}
634	
635	// setKey 在不做重复检查的遍历（Unicode 扫描）中记录一个成功解码的字段名，
636	// 仅维护字段值路径所需的状态。
637	func (t *jsonPathTracker) setKey(name string) {
638		top := t.top()
639		top.lastKey = name
640		top.expectKey = false
641	}
642	
643	// noteInvalidKey 在字段名无法解码（属于 JSON 语法错误）时仅推进键值状态：
644	// 不覆盖已记录的字段名；语法错误留给后续严格 JSON 解码报告。
645	func (t *jsonPathTracker) noteInvalidKey() {
646		t.top().expectKey = false
647	}
648	
649	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
650	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
651	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
652	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
653	// 前缀（"config" 或 "context"）。对象层级、数组下标与字段路径由
654	// jsonPathTracker 统一维护。JSON 语法错误不在此报告（令牌流失效即停止），
655	// 留给严格 JSON 解码。
656	func rejectDuplicateFields(raw []byte, label string) error {
657		dec := json.NewDecoder(bytes.NewReader(raw))
658		// UseNumber：数字以 json.Number 令牌返回而不转 float64，否则超出浮点范围
659		// 的合法数字（如 1e400）会让令牌流提前报错并中止，遮住其后的重复字段。
660		dec.UseNumber()
661		tracker := newJSONPathTracker(label)
662		for {
663			tok, err := dec.Token()
664			if err != nil {
665				// io.EOF 或语法错误；语法错误由后续严格 JSON 解码报告。
666				break
667			}
668			switch t := tok.(type) {
669			case json.Delim:
670				switch t {
671				case '{':
672					tracker.beginContainer(true)
673				case '[':
674					tracker.beginContainer(false)
675				case '}', ']':
676					tracker.endContainer()
677				}
678			case string:
679				if tracker.atKey() {
680					if err := tracker.noteKey(t); err != nil {
681						return err
682					}
683				} else {
684					tracker.endValue()
685				}
686			default:
687				tracker.endValue()
688			}
689		}
690		return nil
691	}
692	
693	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
694	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
695	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
696	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
697	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
698	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
699	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。对象层级、数组
700	// 下标与字段路径由 jsonPathTracker 统一维护；JSON 语法错误不在此报告，留给
701	// Unmarshal。
702	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
703		tracker := newJSONPathTracker(label)
704		i := 0
705		for i < len(raw) {
706			c := raw[i]
707			switch {
708			case c == '{' || c == '[':
709				tracker.beginContainer(c == '{')
710				i++
711			case c == '}' || c == ']':
712				tracker.endContainer()
713				i++
714			case c == '"':
715				end := jsonStringEnd(raw, i)
716				contentEnd := end
717				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
718					contentEnd-- // 去掉右引号；未终止的字符串留给严格 JSON 解码报告
719				}
720				content := raw[i+1 : contentEnd]
721				if tracker.atKey() {
722					if bad := findBadUnicodeEscape(content); bad != nil {
723						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
724							tracker.currentPath(), string(content), bad.escape, bad.detail)
725					}
726					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给严格 JSON 解码。
727					if name, ok := decodeJSONString(raw[i:end]); ok {
728						tracker.setKey(name)
729					} else {
730						tracker.noteInvalidKey()
731					}
732				} else {
733					path := tracker.valuePath()
734					if bad := findBadUnicodeEscape(content); bad != nil {
735						return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
736							path, bad.escape, bad.detail)
737					}
738					tracker.endValue()
739				}
740				i = end
741			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
742				i++
743			default:
744				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
745				for i < len(raw) && !isJSONStructural(raw[i]) {
746					i++
747				}
748				tracker.endValue()
749			}
750		}
751		return nil
752	}
753	
754	// decodeJSONString 解码一个完整的 JSON 字符串字面量（含两侧引号）；ok 为 false
755	// 表示字面量本身非法（未终止或转义写法错误等），属于 JSON 语法错误。
756	func decodeJSONString(lit []byte) (s string, ok bool) {
757		if err := json.Unmarshal(lit, &s); err != nil {
758			return "", false
759		}
760		return s, true
761	}
762	
763	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
764	type badEscape struct {
765		escape string // 原文中的转义序列，如 \uD800
766		detail string // 具体问题（孤立高代理项/孤立低代理项）
767	}
768	
769	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
770	// （右引号之后的下标）；未终止时返回 len(raw)。
771	func jsonStringEnd(raw []byte, i int) int {
772		j := i + 1
773		for j < len(raw) {
774			switch raw[j] {
775			case '\\':
776				j += 2
777			case '"':
778				return j + 1
779			default:
780				j++
781			}
782		}
783		return len(raw)
784	}
785	
786	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
787	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
788	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
789	// 语法错误，不在此报告。
790	func findBadUnicodeEscape(content []byte) *badEscape {
791		j := 0
792		for j < len(content) {
793			if content[j] != '\\' {
794				j++
795				continue
796			}
797			if j+1 >= len(content) {
798				break
799			}
800			if content[j+1] != 'u' {
801				j += 2
802				continue
803			}
804			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
805				j += 2
806				continue
807			}
808			cp := hexVal4(content[j+2 : j+6])
809			switch {
810			case cp >= 0xD800 && cp <= 0xDBFF:
811				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
812				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
813					isHex4(content[j+8:j+12]) {
814					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
815						j += 12
816						continue
817					}
818				}
819				return &badEscape{
820					escape: string(content[j : j+6]),
821					detail: "high surrogate is not followed by a low surrogate",
822				}
823			case cp >= 0xDC00 && cp <= 0xDFFF:
824				return &badEscape{
825					escape: string(content[j : j+6]),
826					detail: "low surrogate is not preceded by a high surrogate",
827				}
828			}
829			j += 6
830		}
831		return nil
832	}
833	
834	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
835	func isJSONStructural(b byte) bool {
836		switch b {
837		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
838			return true
839		}
840		return false
841	}
842	
843	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
844	func isHex4(b []byte) bool {
845		if len(b) != 4 {
846			return false
847		}
848		for _, c := range b {
849			if !isHexDigit(c) {
850				return false
851			}
852		}
853		return true
854	}
855	
856	func isHexDigit(c byte) bool {
857		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
858	}
859	
860	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
861	func hexVal4(b []byte) int {
862		v := 0
863		for _, c := range b {
864			v <<= 4
865			switch {
866			case '0' <= c && c <= '9':
867				v |= int(c - '0')
868			case 'a' <= c && c <= 'f':
869				v |= int(c-'a') + 10
870			default: // 'A' <= c && c <= 'F'
871				v |= int(c-'A') + 10
872			}
873		}
874		return v
875	}
876	
877	func parseFlag(raw any, index int) (Flag, error) {
878		loc := fmt.Sprintf("config.flags[%d]", index)
879		obj, ok := raw.(map[string]any)
880		if !ok {
881			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
882		}
883		key, err := requireNonEmptyString(obj, "key", loc)
884		if err != nil {
885			return Flag{}, err
886		}
887		enabled, err := requireBool(obj, "enabled", loc)
888		if err != nil {
889			return Flag{}, err
890		}
891		def, err := requireBool(obj, "default", loc)
892		if err != nil {
893			return Flag{}, err
894		}
895		rulesArr, err := requireArrayField(obj, "rules", loc)
896		if err != nil {
897			return Flag{}, err
898		}
899		flag := Flag{Key: key, Enabled: enabled, Default: def}
900		seenRules := map[string]int{}
901		for ri, rv := range rulesArr {
902			rule, err := parseRule(rv, index, ri)
903			if err != nil {
904				return Flag{}, err
905			}
906			if prev, dup := seenRules[rule.ID]; dup {
907				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
908			}
909			seenRules[rule.ID] = ri
910			flag.Rules = append(flag.Rules, rule)
911		}
912		return flag, nil
913	}
914	
915	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
916		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
917		obj, ok := raw.(map[string]any)
918		if !ok {
919			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
920		}
921		id, err := requireNonEmptyString(obj, "id", loc)
922		if err != nil {
923			return Rule{}, err
924		}
925		value, err := requireBool(obj, "value", loc)
926		if err != nil {
927			return Rule{}, err
928		}
929		condsArr, err := requireArrayField(obj, "conditions", loc)
930		if err != nil {
931			return Rule{}, err
932		}
933		if len(condsArr) == 0 {
934			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
935		}
936		rule := Rule{ID: id, Value: value}
937		for ci, cv := range condsArr {
938			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
939			if err != nil {
940				return Rule{}, err
941			}
942			rule.Conditions = append(rule.Conditions, cond)
943		}
944		return rule, nil
945	}
946	
947	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
948		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
949		obj, ok := raw.(map[string]any)
950		if !ok {
951			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
952		}
953		attribute, err := requireNonEmptyString(obj, "attribute", loc)
954		if err != nil {
955			return Condition{}, err
956		}
957		op, err := requireNonEmptyString(obj, "op", loc)
958		if err != nil {
959			return Condition{}, err
960		}
961		valueField, err := requireField(obj, "value", loc)
962		if err != nil {
963			return Condition{}, err
964		}
965		cond := Condition{Attribute: attribute, Op: op}
966		switch op {
967		case "eq":
968			s, ok := valueField.(string)
969			if !ok {
970				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
971			}
972			cond.strVal = s
973		case "in":
974			arr, ok := valueField.([]any)
975			if !ok {
976				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
977			}
978			if len(arr) == 0 {
979				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
980			}
981			for ii, item := range arr {
982				s, ok := item.(string)
983				if !ok {
984					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
985				}
986				cond.inVal = append(cond.inVal, s)
987			}
988		default:
989			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
990		}
991		return cond, nil
992	}
993	
994	func requireField(obj map[string]any, name, loc string) (any, error) {
995		v, ok := obj[name]
996		if !ok {
997			return nil, fmt.Errorf("%s: field is required", appendFieldPath(loc, name))
998		}
999		if v == nil {
1000			return nil, fmt.Errorf("%s: must not be null", appendFieldPath(loc, name))
1001		}
1002		return v, nil
1003	}
1004	
1005	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
1006		v, err := requireField(obj, name, loc)
1007		if err != nil {
1008			return nil, err
1009		}
1010		arr, ok := v.([]any)
1011		if !ok {
1012			return nil, fmt.Errorf("%s: must be an array", appendFieldPath(loc, name))
1013		}
1014		return arr, nil
1015	}
1016	
1017	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
1018		v, err := requireField(obj, name, loc)
1019		if err != nil {
1020			return "", err
1021		}
1022		s, ok := v.(string)
1023		if !ok {
1024			return "", fmt.Errorf("%s: must be a string", appendFieldPath(loc, name))
1025		}
1026		if s == "" {
1027			return "", fmt.Errorf("%s: must not be empty", appendFieldPath(loc, name))
1028		}
1029		return s, nil
1030	}
1031	
1032	func requireBool(obj map[string]any, name, loc string) (bool, error) {
1033		v, err := requireField(obj, name, loc)
1034		if err != nil {
1035			return false, err
1036		}
1037		b, ok := v.(bool)
1038		if !ok {
1039			return false, fmt.Errorf("%s: must be a boolean", appendFieldPath(loc, name))
1040		}
1041		return b, nil
1042	}
