255	// inCfg 拼出只有一个启用开关、一条 in 规则（id=r1、value=true、default=false）
256	// 的配置；attrJSON 是属性名的 JSON 字符串内容，listJSON 是完整的候选值数组。
257	func inCfg(attrJSON, listJSON string) string {
258		return `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
259			`{"id":"r1","value":true,"conditions":[` +
260			`{"attribute":"` + attrJSON + `","op":"in","value":` + listJSON + `}]}]}]}`
261	}
