473	// TestInEarlierFalseVsLaterTrueRule 验证 in 的精确成员判断与规则定案顺序的配合：
474	// 前面的 in 规则返回 false、后面的规则返回 true 且上下文可同时满足两者时，
475	// 只有列表精确命中（含直接字符与转义两种写法）才由前一条以 reason=rule、
476	// ruleId 指向前一条定案 false；外形相近的“伪命中”必须继续采用后面的规则；
477	// 没有任何规则成立时仍采用 default、ruleId 为 null。
478	func TestInEarlierFalseVsLaterTrueRule(t *testing.T) {
479		cfg := `{"flags":[{"key":"f","enabled":true,"default":true,"rules":[
480			{"id":"r-deny","value":false,"conditions":[
481				{"attribute":"plan","op":"eq","value":"pro"},
482				{"attribute":"tier","op":"in","value":["é","a"]}]},
483			{"id":"r-allow","value":true,"conditions":[
484				{"attribute":"region","op":"eq","value":"cn"}]}]}]}`
485		denyID, allowID := "r-deny", "r-allow"
486	
487		// 精确命中：前一条立即定案 false，后一条同时成立也不能翻转。
488		for _, ctxRaw := range []string{
489			`{"plan":"pro","tier":"é","region":"cn"}`,
490			`{"plan":"pro","tier":"` + inEscEAcute + `","region":"cn"}`,
491			`{"plan":"pro","tier":"a","region":"cn"}`,
492		} {
493			got := eval(t, cfg, "f", ctxRaw)
494			want := EvalResult{Key: "f", Value: false, Reason: EvalRule, RuleID: &denyID}
495			if !got.Equals(want) {
496				t.Fatalf("exact in-match must lock the earlier false rule (%s): got %+v", ctxRaw, got)
497			}
498		}
499	
500		// 外形相近但解码后不相等，或属性缺失：前一条不成立，后一条 r-allow 获胜。
501		for _, tc := range []struct {
502			name string
503			ctx  string
504		}{
505			{"combining sequence", `{"plan":"pro","tier":"` + inEscCombine + `","region":"cn"}`},
506			{"uppercase member", `{"plan":"pro","tier":"A","region":"cn"}`},
507			{"surrounding whitespace", `{"plan":"pro","tier":" a","region":"cn"}`},
508			{"replacement char", `{"plan":"pro","tier":"` + inEscReplace + `","region":"cn"}`},
509			{"missing tier", `{"plan":"pro","region":"cn"}`},
510		} {
511			t.Run(tc.name, func(t *testing.T) {
512				got := eval(t, cfg, "f", tc.ctx)
513				want := EvalResult{Key: "f", Value: true, Reason: EvalRule, RuleID: &allowID}
514				if !got.Equals(want) {
515					t.Fatalf("lookalike miss must continue to the later rule: got %+v, want %+v", got, want)
516				}
517			})
518		}
519	
520		// 两条规则都不成立：采用 default=true、ruleId=null。
521		got := eval(t, cfg, "f", `{"plan":"free","tier":"é","region":"eu"}`)
522		want := EvalResult{Key: "f", Value: true, Reason: EvalDefault, RuleID: nil}
523		if !got.Equals(want) {
524			t.Fatalf("no rule holds must use default: got %+v, want %+v", got, want)
525		}
526	}
